const stone = find_block({ names: ['stone', 'andesite', 'diorite', 'granite'], max_distance: 24 });
if (!stone) {
  const here = position();
  await move_to(here.x + 12, here.y, here.z + 12);
  return { done: false, detail: 'no stone here; walking on' };
}
const dug = await dig(stone.x, stone.y, stone.z);
if (!dug.ok) {
  return { done: false, detail: dug.detail };
}
await leave_at_depot();  // the bag, in one standing — walking away between items takes the pile back
return { done: true, detail: 'mined stone and left the bag at the depot' };
